import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';import '../domain/reminder_recurrence.dart';
class CalendarScreen extends ConsumerStatefulWidget{const CalendarScreen({super.key,this.petId});final String? petId;@override ConsumerState<CalendarScreen> createState()=>_CalendarScreenState();}
class _CalendarScreenState extends ConsumerState<CalendarScreen>{DateTime selected=DateTime.now();List<_Occurrence> _eventsForDay(List<Reminder> reminders,DateTime day){final start=DateTime(day.year,day.month,day.day),end=start.add(const Duration(days:1)),monthStart=DateTime(day.year,day.month,1),monthEnd=DateTime(day.year,day.month+1,1);final events=<_Occurrence>[];for(final reminder in reminders){if(!reminder.enabled||reminder.completed)continue;var cursor=reminder.dueAt;if(reminder.repeat=='once'){if(!cursor.isBefore(start)&&cursor.isBefore(end))events.add(_Occurrence(reminder,cursor));continue;}var guard=0;while(cursor.isBefore(monthStart)&&guard<5000){final next=ReminderRecurrence.next(cursor,reminder.repeat,intervalDays:reminder.intervalDays,weekdays:reminder.weekdays,monthEndPolicy:reminder.monthEndPolicy);if(next==null||!next.isAfter(cursor))break;cursor=next;guard++;}guard=0;while(cursor.isBefore(monthEnd)&&guard<100){if(!cursor.isBefore(start)&&cursor.isBefore(end))events.add(_Occurrence(reminder,cursor));final next=ReminderRecurrence.next(cursor,reminder.repeat,intervalDays:reminder.intervalDays,weekdays:reminder.weekdays,monthEndPolicy:reminder.monthEndPolicy);if(next==null||!next.isAfter(cursor))break;cursor=next;guard++;}}events.sort((a,b)=>a.when.compareTo(b.when));return events;}
@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider);final all=c.items('reminders').map(Reminder.fromMap).where((e)=>widget.petId==null||e.petId==widget.petId).toList();final events=_eventsForDay(all,selected);return Scaffold(appBar:AppBar(title:const Text('Calendar agenda')),body:ListView(padding:const EdgeInsets.all(16),children:[CalendarDatePicker(initialDate:selected,firstDate:DateTime(2020),lastDate:DateTime(2100),onDateChanged:(d)=>setState(()=>selected=d)),Text(DateFormat.yMMMMd().format(selected),style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),if(events.isEmpty)const Text('No reminders on this day.')else ...events.map((e)=>Card(child:ListTile(leading:const Icon(Icons.event,color:Color(0xFF39845A)),title:Text(e.reminder.title),subtitle:Text('${e.reminder.category} · ${DateFormat.jm().format(e.when)} · ${e.reminder.repeat}'))))]));}}
class _Occurrence{const _Occurrence(this.reminder,this.when);final Reminder reminder;final DateTime when;}
